create table public.platform_admins(user_id uuid primary key references auth.users on delete cascade); alter table public.platform_admins enable row level security; revoke all on public.platform_admins from anon,authenticated; grant select on public.platform_admins to authenticated; grant all on public.platform_admins to service_role; create policy own_admin_role on public.platform_admins for select to authenticated using(user_id=(select auth.uid())); create policy admin_restaurants on public.restaurants for select to authenticated using(exists(select 1 from public.platform_admins a where a.user_id=(select auth.uid())));